    private static Map<String, Operation<?>> all(Operation<?>... operations) {
        Map<String, Operation<?>> all = new LinkedHashMap<>();
        for (Operation<?> operation : operations) {
            all.put(operation.key(), operation);
        }
        return Collections.unmodifiableMap(all);
    }

    @SuppressWarnings("unchecked")
    private static Map<Integer, List<String>> errors(Object... statusAndNames) {
        Map<Integer, List<String>> errors = new LinkedHashMap<>();
        for (int i = 0; i < statusAndNames.length; i += 2) {
            errors.put((Integer) statusAndNames[i], (List<String>) statusAndNames[i + 1]);
        }
        return Collections.unmodifiableMap(errors);
    }
